.ds {
  color:var(--p-ink); background:var(--p-bg); font:var(--p-type-body);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset); }
.ds .ui-icon { display:inline-block; width:var(--p-icon-md); height:var(--p-icon-md); flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--p-text-sm); margin-top:var(--p-space-sm); min-height:calc(var(--p-space-unit) * 5); color:var(--p-muted); }
.ds .ds-surface { border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); background:var(--p-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--p-shadow); border-color:var(--p-edge); }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--p-inset); background:var(--p-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--p-high); box-shadow:var(--p-glass-shadow); }
@supports (backdrop-filter:blur(16px)) { .ds .ds-surface[data-material="glass"] { background:var(--p-glass); backdrop-filter:var(--p-blur-md); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--p-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }
.ds .ds-token-row { display:flex; flex-wrap:wrap; align-items:center; gap:var(--p-space-sm); }

.ds .ds-card { display:flex; flex-direction:column; height:100%; background:var(--p-surface); border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); box-shadow:var(--p-raised); overflow:hidden; }
.ds .ds-card[data-selected="true"] { border-color:var(--p-success); background:var(--p-selected-surface); }
.ds .ds-card-body { flex:1; padding:var(--p-space-lg); }
.ds .ds-card h3 { font-size:var(--p-text-title); line-height:var(--p-leading-snug); font-weight:var(--p-weight-semibold); letter-spacing:var(--p-tracking-tighter); margin-top:var(--p-space-md); }
.ds .ds-card p { font-size:var(--p-text-body); color:var(--p-muted); margin-top:var(--p-space-xs); }
.ds .ds-card-actions { display:flex; justify-content:flex-end; padding:var(--p-space-md) var(--p-space-lg); }
/* Looks (Material 3 elevated · filled · outlined): :where keeps each look as weak as the base rule, so a selected card still shows its selected state. */
.ds .ds-card:where([data-look="filled"]) { border-color:transparent; background:var(--p-tile); box-shadow:none; }
.ds .ds-card:where([data-look="outlined"]) { background:var(--p-bg); box-shadow:none; }

